const $=id=>document.getElementById(id);let recognition=null,listening=false,base='',hadError=false;
function message(text){$('status').textContent=text;$('status').hidden=!text}
function openNote(){ $('app').classList.add('editing');$('composer').hidden=false;$('orb').setAttribute('aria-expanded','true');$('heading').textContent='想说的，想记的';$('hint').textContent='写下来，或说给这里听'; }
function stop(){if(recognition&&listening)recognition.stop()}
function collapse(){stop();$('app').classList.remove('editing');$('composer').hidden=true;$('orb').setAttribute('aria-expanded','false');$('heading').textContent='记下这一刻';$('hint').textContent=$('note').value.trim()?'文字已暂存，轻触继续编辑':'轻触一下，让想法留下来';$('orb').focus()}
$('orb').onclick=()=>{if(listening){stop();return}openNote();$('note').focus()};$('close').onclick=collapse;$('done').onclick=collapse;$('note').oninput=()=>{$('done').disabled=!$('note').value.trim()};
$('voice').onclick=()=>{if(listening){stop();return}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){message('当前浏览器不支持语音转文字，可使用手机键盘的语音输入，或直接打字。');return}recognition=new Speech();recognition.lang='zh-CN';recognition.continuous=true;recognition.interimResults=true;base=$('note').value;hadError=false;
recognition.onstart=()=>{listening=true;$('app').classList.add('recording');$('voiceLabel').textContent='停止录音';message('正在聆听…说完后点击停止录音。')};
recognition.onresult=event=>{let transcript='';for(let i=0;i<event.results.length;i++)transcript+=event.results[i][0].transcript;$('note').value=base+(base&&!base.endsWith('\n')?'\n':'')+transcript;$('note').oninput()};
recognition.onerror=event=>{hadError=true;const errors={'not-allowed':'麦克风未获授权，请在浏览器中允许麦克风权限后重试。','no-speech':'没有听清，再试一次吧。','network':'语音服务暂时无法连接，请重试或直接打字。','audio-capture':'没有找到可用的麦克风，请检查设备。','aborted':'语音输入已停止。'};message(errors[event.error]||'语音输入暂时不可用，请重试或直接打字。')};
recognition.onend=()=>{listening=false;$('app').classList.remove('recording');$('voiceLabel').textContent='语音输入';if(!hadError)message('语音输入已结束，可以继续编辑。')};try{recognition.start()}catch{message('无法启动语音输入，请稍后再试。')}};
const quickActions=['menu-quick','menu-text','menu-start'];for(const id of quickActions){$(id).onclick=()=>{openNote();$('note').focus()}};$('menu-voice').onclick=()=>{openNote();$('voice').click()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('composer').hidden)collapse()});window.addEventListener('pagehide',stop);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'stage_note',description:'打开输入区并填入草稿，不保存或发送记录。',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(typeof input?.text!=='string'||Object.keys(input).some(k=>k!=='text'))throw new Error('Expected text only');openNote();$('note').value=input.text;$('note').oninput();return{status:'draft',text:$('note').value}}})).catch(()=>{})}catch{}}
